#!/bin/sh
# Elimina los datos de SIGF inmediatamente, sin confirmaciones.
set -eu
if [ "$(id -u)" = 0 ]; then
  usuario=${SUDO_USER:-}
  if [ -z "$usuario" ] || [ "$usuario" = root ]; then
    usuario=$(stat -f '%Su' /dev/console 2>/dev/null || true)
  fi
  if [ -z "$usuario" ] || [ "$usuario" = root ] || [ "$usuario" = loginwindow ]; then
    echo 'No se pudo identificar al usuario de macOS. Ejecute el script desde su cuenta normal, sin sudo.' >&2
    exit 1
  fi
  exec sudo -n -H -u "$usuario" -- "$0" "$@"
fi
root=$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)
tmp=$(mktemp -d "${TMPDIR:-/tmp}/sigf-reset.XXXXXXXX")
trap 'rm -rf "$tmp"' EXIT HUP INT TERM
jar="$HOME/.m2/repository/org/postgresql/postgresql/42.7.5/postgresql-42.7.5.jar"
[ -f "$jar" ] || { echo 'Falta el controlador PostgreSQL de Maven.' >&2; exit 1; }
printf '%s' '' | base64 -D > "$tmp/ResetAutomatico.java" 2>/dev/null || printf '%s' '' | base64 -d > "$tmp/ResetAutomatico.java"
javac -encoding UTF-8 -d "$tmp" "$root/src/main/java/org/sigf/config/SecureConnectionStore.java" "$tmp/ResetAutomatico.java"
java -cp "$tmp:$jar" ResetAutomatico
